importScripts("sha1.js");var SLICE_BYTES=4*1024*1024;function readSlice(e){return typeof FileReaderSync!="undefined"?Promise.resolve((new FileReaderSync).readAsArrayBuffer(e)):e.arrayBuffer()}self.onmessage=function(e){var n=e.data.id,s=e.data.file,o=new FGSSha1,t=0;function i(){if(t>=s.size){self.postMessage({id:n,type:"done",hex:o.digest()});return}var e=Math.min(t+SLICE_BYTES,s.size);readSlice(s.slice(t,e)).then(function(s){o.update(new Uint8Array(s)),t=e,self.postMessage({id:n,type:"progress",bytes:t}),i()}).catch(function(e){self.postMessage({id:n,type:"error",message:String(e)})})}try{i()}catch(e){self.postMessage({id:n,type:"error",message:String(e)})}}